import {itemTexture} from './item-icons.js';
import {drawSprite} from './sprite-art.js';
const cards=[...document.querySelectorAll('.card')],audios=cards.map(c=>c.querySelector('audio')),status=document.querySelector('#audioStatus');
for(const card of cards){const a=card.querySelector('audio'),button=document.createElement('button');button.className='preview';button.textContent=a.getAttribute('aria-label');button.onclick=()=>{a.currentTime=0;a.play().catch(()=>status.textContent='播放未成功，请用下方播放器重试。')};card.append(button)}
for(const a of audios){a.volume=.38;a.onplay=()=>{for(const b of audios)if(b!==a)b.pause();status.textContent='正在试听：'+a.getAttribute('aria-label').replace('试听','')};a.onended=()=>status.textContent='试听结束，可以进入实战演示。';a.onerror=()=>status.textContent='音频加载失败，请刷新后重试。'}
document.addEventListener('visibilitychange',()=>{if(document.hidden)audios.forEach(a=>a.pause())});window.addEventListener('pagehide',()=>audios.forEach(a=>a.pause()));
function frame(){for(const card of cards){const a=card.querySelector('audio'),canvas=card.querySelector('canvas'),c=canvas.getContext('2d'),moving=!a.paused&&!a.ended,f=moving?3+Math.floor(a.currentTime*5)%3:0;c.imageSmoothingEnabled=false;c.clearRect(0,0,280,180);c.fillStyle='#bdc29a';c.fillRect(70,151,140,7);if(canvas.dataset.item){const t=itemTexture(canvas.dataset.item);drawSprite(c,t.file,t.index%t.cols,Math.floor(t.index/t.cols),t.cols,t.rows,140,134,125)}else drawSprite(c,canvas.dataset.boss==='bull'?'bull-actions-v2.png':'meishu-actions-v1.png',f%4,Math.floor(f/4),4,2,140,134,140)}requestAnimationFrame(frame)}frame();
